const generationModeSchema = z.enum(["text", "image", "video", "audio"]);
const assetCategorySchema = z.enum(["character", "environment", "prop", "material", "other"]);
const agentCandidateCategorySchema = z.enum(["environment", "prop", "material", "other"]);
const projectIdSchema = z.string().min(1).optional();
const projectCandidateSchema = z.object({ unitId: z.string().optional(), shotId: z.string().optional(), name: z.string().min(1), category: agentCandidateCategorySchema, details: recordSchema.optional() });
const projectShotSchema = z.object({ id: z.string().optional(), unitId: z.string().optional(), title: z.string().min(1), description: z.string().optional(), position: z.number().int().min(0).optional(), durationMs: z.number().int().min(0).optional(), status: z.string().optional() });
const canvasReadSelector = { canvasId: z.string().min(1).optional(), clientId: z.string().min(1).optional() };
// Script 分镜行：字段与画布真实 StoryboardRow 对齐，只做输入校验，不重复实现分镜逻辑。
const storyboardCharacterSchema = z.object({
    characterName: z.string().min(1),
    characterAssetId: z.string().nullable().optional(),
    characterVersionId: z.string().nullable().optional(),
    characterDescription: z.string().nullable().optional(),
    characterImageNodeId: z.string().nullable().optional(),
}).strict();
const storyboardAssetBindingSchema = z.object({
    nodeId: z.string().min(1),
    role: z.enum(["character", "environment", "wardrobe", "prop", "weapon", "style", "motion", "audio"]),
    priority: z.number().nullable().optional(),
}).strict();
const storyboardSegmentBindingSchema = z.object({
    segmentId: z.string().min(1),
    order: z.number().int().min(0),
    videoNodeId: z.string().nullable().optional(),
    taskId: z.string().nullable().optional(),
    resourceId: z.string().nullable().optional(),
    stepId: z.string().nullable().optional(),
    attemptId: z.string().nullable().optional(),
    relayReferenceNodeId: z.string().nullable().optional(),
    inputFingerprint: z.string().nullable().optional(),
    model: z.string().nullable().optional(),
    capabilityRevision: z.string().nullable().optional(),
    requestedDurationSeconds: z.number().finite().min(0).nullable().optional(),
    timelineStartMs: z.number().int().nonnegative().nullable().optional(),
    timelineDurationMs: z.number().int().nonnegative().nullable().optional(),
    status: z.enum(["planned", "submitted", "running", "succeeded", "failed", "uncertain", "cancelled"]).nullable().optional(),
}).strict();
const storyboardRowSchema = z.object({
    id: z.string().optional(),
    sceneId: z.string().nullable().optional(),
    shotNumber: z.number().int().min(1).optional(),
    // durationSeconds 是叙事镜头目标时长，不等于单次模型请求时长。
    durationSeconds: z.number().finite().min(0).max(3600).nullable().optional(),
    plotDescription: z.string().nullable().optional(),
    dialogue: z.string().nullable().optional(),
    voiceover: z.string().nullable().optional(),
    characters: z.array(storyboardCharacterSchema).optional(),
    narrativeIntent: z.string().nullable().optional(),
    viewerPOV: z.string().nullable().optional(),
    performanceBlocking: z.string().nullable().optional(),
    shotSize: z.string().nullable().optional(),
    emotion: z.string().nullable().optional(),
    lightingAndAtmosphere: z.string().nullable().optional(),
    audioEffects: z.string().nullable().optional(),
    camera: z.string().nullable().optional(),
    motion: z.string().nullable().optional(),
    timeBeats: z.string().nullable().optional(),
    imageGenerationPrompt: z.string().nullable().optional(),
    videoMotionPrompt: z.string().nullable().optional(),
    imagePromptTemplateVariables: z.record(z.string()).nullable().optional(),
    videoPromptTemplateVariables: z.record(z.string()).nullable().optional(),
    mustHave: z.array(z.string()).nullable().optional(),
    optionalDetails: z.array(z.string()).nullable().optional(),
    continuityOut: z.string().nullable().optional(),
    negativePrompt: z.string().nullable().optional(),
    assetBindings: z.array(storyboardAssetBindingSchema).nullable().optional(),
    requiredAssetRoles: z.array(z.enum(["character", "environment", "wardrobe", "prop", "weapon", "style", "motion", "audio"])).nullable().optional(),
    videoOperation: z.enum(["text_to_video", "image_to_video", "reference_to_video", "audio_to_video", "extend"]).nullable().optional(),
    imageNodeId: z.string().nullable().optional(),
    videoNodeId: z.string().nullable().optional(),
    segmentBindings: z.array(storyboardSegmentBindingSchema).nullable().optional(),
    status: z.enum(["idle", "ready", "success", "loading", "error"]).nullable().optional(),
    errorDetails: z.string().nullable().optional(),
}).strict().superRefine((row, context) => {
    if (!row.segmentBindings)
        return;
    const ids = new Set();
    const orders = new Set();
    row.segmentBindings.forEach((binding, index) => {
        if (ids.has(binding.segmentId))
            context.addIssue({ code: "custom", path: ["segmentBindings", index, "segmentId"], message: "segmentId 必须在分镜行内唯一" });
        if (orders.has(binding.order))
            context.addIssue({ code: "custom", path: ["segmentBindings", index, "order"], message: "片段顺序必须在分镜行内唯一" });
        ids.add(binding.segmentId);
        orders.add(binding.order);
    });
});
