const directorVec3Schema = z.tuple([z.number().finite().min(-100000).max(100000), z.number().finite().min(-100000).max(100000), z.number().finite().min(-100000).max(100000)]);
const directorScaleSchema = z.tuple([z.number().finite().min(-1000).max(1000), z.number().finite().min(-1000).max(1000), z.number().finite().min(-1000).max(1000)]).refine((scale) => scale.every((value) => Math.abs(value) >= 0.001));
